package com.tripmateai.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.time.LocalDate; import java.util.*;
@Entity @Table(name="travel_journals",indexes=@Index(name="idx_journal_trip_date",columnList="trip_id,journal_date")) @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true,onlyExplicitlyIncluded=true) @ToString
public class TravelJournal extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="trip_id",nullable=false) @ToString.Exclude private Trip trip; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) @ToString.Exclude private User user; @NotNull @Column(name="journal_date",nullable=false) private LocalDate journalDate; @NotBlank @Size(max=250) @Column(nullable=false,length=250) private String title; @Size(max=10000) @Column(nullable=false,columnDefinition="TEXT") private String content; @OneToMany(mappedBy="journal",fetch=FetchType.LAZY,cascade=CascadeType.ALL,orphanRemoval=true) @ToString.Exclude private List<JournalPhoto> photos=new ArrayList<>(); }
